const lines = stdin.trim().split('\n');
const budget = parseInt(lines[0], 10);
const files = lines.slice(1).map((line, index) => {
  const [path, chars, priority] = line.split('|');
  return { path: path.trim(), tokens: Math.ceil(Number(chars) / 4), priority: Number(priority), index };
});
files.sort((a, b) => a.priority - b.priority || a.index - b.index);
let used = 0;
const included = [];
const skipped = [];
for (const f of files) {
  if (used + f.tokens <= budget) {
    used += f.tokens;
    included.push(f.path);
  } else {
    skipped.push(f.path);
  }
}
console.log('Included: ' + (included.length ? included.join(', ') : 'none'));
console.log('Skipped: ' + (skipped.length ? skipped.join(', ') : 'none'));
console.log(`Tokens used: ${used}/${budget}`);
